//! Unicode 12.1 code point properties of the standard tokenizer.
//!
//! Generated by `generate_tables.py` from the Unicode 12.1.0 `WordBreakProperty.txt`,
//! `LineBreak.txt` and `Scripts.txt` and the emoji 12.1 `emoji-data.txt`, including its
//! reserved `Extended_Pictographic` ranges. Regenerate it with that script; never edit it by
//! hand. A code point absent from [`CODE_POINT_RANGES`] has `Word_Break=Other`, no script of
//! interest and no flag.

/// The `Word_Break` values the tokenizer distinguishes; `CR`, `LF`, `Newline` and
/// `WSegSpace` break like `Other`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) enum WordBreak {
    /// `Word_Break=Other`.
    Other,
    /// `Word_Break=ALetter`.
    ALetter,
    /// `Word_Break=Hebrew_Letter`.
    HebrewLetter,
    /// `Word_Break=Numeric`.
    Numeric,
    /// `Word_Break=Katakana`.
    Katakana,
    /// `Word_Break=MidLetter`.
    MidLetter,
    /// `Word_Break=MidNumLet`.
    MidNumLet,
    /// `Word_Break=MidNum`.
    MidNum,
    /// `Word_Break=Single_Quote`.
    SingleQuote,
    /// `Word_Break=Double_Quote`.
    DoubleQuote,
    /// `Word_Break=ExtendNumLet`.
    ExtendNumLet,
    /// `Word_Break=Regional_Indicator`.
    RegionalIndicator,
    /// `Word_Break=Extend`.
    Extend,
    /// `Word_Break=Format`.
    Format,
    /// `Word_Break=ZWJ`.
    Zwj,
}

/// The scripts the tokenizer distinguishes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) enum Script {
    /// Any script other than the three below.
    Other,
    /// `Script=Han`.
    Han,
    /// `Script=Hiragana`.
    Hiragana,
    /// `Script=Hangul`.
    Hangul,
}

/// Flag: `Line_Break=SA (Complex_Context)`.
pub(super) const COMPLEX_CONTEXT: u8 = 0b0000_0001;
/// Flag: `Emoji`.
pub(super) const EMOJI: u8 = 0b0000_0010;
/// Flag: `Emoji_Modifier`.
pub(super) const EMOJI_MODIFIER: u8 = 0b0000_0100;
/// Flag: `Emoji_Modifier_Base`.
pub(super) const EMOJI_MODIFIER_BASE: u8 = 0b0000_1000;
/// Flag: `Extended_Pictographic`.
pub(super) const EXTENDED_PICTOGRAPHIC: u8 = 0b0001_0000;

